import json,os,html,shutil,re
from pathlib import Path
from urllib.parse import quote
from datetime import date
root=Path(__file__).resolve().parents[1];out=root/'site'; data=json.loads((root/'content/articles.json').read_text(encoding='utf-8')); state=json.loads((root/'content/state.json').read_text());queue=[a for a in data if not a['published']]; visible=[a for a in data if a['published']]+queue[:state['released_count']]
if out.exists():shutil.rmtree(out)
out.mkdir();(out/'posts').mkdir();shutil.copy(root/'assets/style.css',out/'style.css')
E=html.escape
cats=['전체','면역의 기초','면역세포','음식과 영양','활성산소','암의 이해','암 종류별','병원과 보험','논문 읽기']
def layout(title,desc,prefix,body):
 nav=''.join('<a href="'+prefix+'index.html'+q+'#articles">'+E(label)+'</a>' for label,q in [('전체 글',''),('면역·NK세포','?category=면역세포'),('암 종류','?category=암 종류별'),('병원·보험','?category=병원과 영양' .replace('영양','보험'))])
 return f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)} | 면역력이 힘이다</title><meta name="description" content="{E(desc,quote=True)}"><meta property="og:type" content="article"><meta property="og:title" content="{E(title,quote=True)}"><meta property="og:description" content="{E(desc,quote=True)}"><link rel="stylesheet" href="{prefix}style.css"></head><body><header><nav class="wrap"><a class="brand" href="{prefix}index.html"><span class="mark">✳</span><span>면역력이 힘이다<small>IMMUNE & CANCER JOURNAL</small></span></a><div class="navlinks">{nav}</div></nav></header>{body}<footer><div class="wrap"><strong>면역력이 힘이다</strong><p>건강 정보를 차분하게, 근거와 함께 살펴봅니다.</p><p>콘텐츠는 일반적인 정보 제공을 위한 것이며 개인의 진단이나 치료를 대신하지 않습니다.</p></div></footer></body></html>'''
cards=''.join(f'''<a class="card" href="posts/{a['id']}.html" data-category="{E(a['category'])}"><span class="tag">{E(a['category'])}</span><h3>{E(a['title'])}</h3><p>{E(a['summary'])}</p><span class="more">자세히 읽기</span></a>''' for a in visible)
buttons=''.join(f'<button type="button" data-filter="{E(x)}" class="{"active" if x=="전체" else ""}">{E(x)}</button>' for x in cats)
body=f'''<main><section class="hero"><div class="wrap hero-grid"><div><div class="eyebrow">IMMUNITY & HEALTH JOURNAL</div><h1>몸을 이해하는<br><em>건강한 첫걸음</em></h1><p class="lead">면역세포부터 암의 이해, 병원과 보험까지.<br>궁금했던 건강 정보를 하나씩, 쉽게 풀어드립니다.</p><a class="cta" href="#articles">전체 글 둘러보기</a></div><div class="hero-art cell-stage" aria-hidden="true"><div class="cell-scene"><div class="cell-aura"></div><div class="cell-core"><div class="cell-nucleus"></div><i class="cell-speck s1"></i><i class="cell-speck s2"></i><i class="cell-speck s3"></i><i class="cell-speck s4"></i></div><div class="cell-orbit orbit-a"><i></i></div><div class="cell-orbit orbit-b"><i></i></div><div class="cell-orbit orbit-c"><i></i></div></div><span class="cell-caption">IMMUNE CELL · CONCEPT VISUAL</span></div></div></section><div class="wrap"><div class="categories"><div><b>면역과 건강</b><span>음식부터 면역세포까지</span></div><div><b>암을 이해하다</b><span>진단·병기·치료 이야기</span></div><div><b>진료를 준비하다</b><span>병원과 보험 정보</span></div></div><section id="articles"><div class="section-head"><div><span class="eyebrow">EXPLORE OUR STORIES</span><h2>궁금했던 이야기를 찾아보세요</h2></div><p>작은 궁금증부터 차근차근 읽어보세요.</p></div><div class="filters">{buttons}</div><div class="grid">{cards}</div><p id="empty" hidden>아직 등록된 글이 없습니다. 새로운 글을 준비하고 있습니다.</p></section><section class="note"><div><span class="eyebrow">READ WITH CONFIDENCE</span><h2>정보의 출처를 함께 확인하세요</h2><p>글마다 참고 자료를 연결해 연구와 제도의 내용을 직접 살펴볼 수 있도록 했습니다.</p></div><a href="#articles">글 살펴보기</a></section></div></main><script>document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active');let n=0;document.querySelectorAll('[data-category]').forEach(c=>{{c.hidden=b.dataset.filter!=='전체'&&c.dataset.category!==b.dataset.filter;if(!c.hidden)n++}});document.getElementById('empty').hidden=n!==0}}));const selected=new URLSearchParams(location.search).get('category');if(selected){{const button=[...document.querySelectorAll('[data-filter]')].find(b=>b.dataset.filter===selected);if(button)button.click()}}</script>'''
(out/'index.html').write_text(layout('면역과 암을 이해하는 첫걸음','면역세포, 음식, 암과 건강 정보를 근거와 함께 알아봅니다.','',body),encoding='utf-8')
for a in visible:
 sections=''.join(f'<section><h2>{E(h)}</h2><p>{E(t)}</p></section>' for h,t in a['sections'])
 sources=''.join(f'<li><a href="{E(u,quote=True)}" target="_blank" rel="noopener noreferrer">{E(label)}</a></li>' for label,u in a['sources'])
 body=f'''<main class="wrap"><article class="article"><p class="crumb"><a href="../index.html">홈</a> / {E(a['category'])}</p><span class="tag">{E(a['category'])}</span><h1>{E(a['title'])}</h1><p class="description">{E(a['summary'])}</p><div class="meta">자료 확인일 2026.11.24 · 면역력이 힘이다</div><div class="summary"><b>이 글에서 알아볼 내용</b><p>{E(a['summary'])}</p></div>{sections}<div class="disclaimer">이 글은 일반적인 정보이며 개인의 진단·치료 또는 보험 보장을 결정하지 않습니다. 실제 진료 및 제도 적용은 담당 의료진·해당 기관과 확인하세요.</div><section class="references"><h2>참고 자료</h2><ul>{sources}</ul></section><a class="back" href="../index.html#articles">전체 글 보기</a></article></main>'''
 (out/'posts'/f"{a['id']}.html").write_text(layout(a['title'],a['summary'],'../',body),encoding='utf-8')
repo=os.getenv('GITHUB_REPOSITORY','');custom=os.getenv('SITE_URL','').rstrip('/')
if custom: base=custom+'/'
elif '/' in repo:
 owner,name=repo.split('/',1);base='https://'+owner+'.github.io/'+('' if name.lower()==(owner+'.github.io').lower() else quote(name)+'/')
else:base=''
(out/'robots.txt').write_text('User-agent: *\nAllow: /\n'+('Sitemap: '+base+'sitemap.xml\n' if base else ''),encoding='utf-8')
if base:
 urls=[base]+[base+'posts/'+quote(x['id'])+'.html' for x in visible];(out/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+E(u)+'</loc></url>' for u in urls)+'</urlset>',encoding='utf-8')
print('built',len(visible),'published articles; queue left:',len(queue)-state['released_count'])
